$(function(){let l=document.getElementsByClassName("t4s-swatch__item"),n=document.getElementById("x1_mark");for(let e=0;e<l.length;e++){const t=l[e];let i=t.innerText;i.indexOf("Black")!==-1?t.onclick=()=>{n.style.display="none"}:i.indexOf("Brown")!==-1&&(t.onclick=()=>{n.style.display="block"})}});
